/**
 * Checks the shared SR1 vectors (docs/vectors/sr1.json, generated by the Lua addon) with the
 * TypeScript reference (tools/sr1/sr1.ts) and the REAL web engine + verifyLog. READ-ONLY on the web repo.
 *
 *   bun tools/sr1/check_vectors.ts <path-to-stackrivals-practice-arena> [docs/vectors/sr1.json]
 *
 * PASS means: Lua encoder == TS decoder/encoder, and Lua's replay/verification == the web's.
 */
import { readFileSync } from "node:fs";
import { decodeChallenge, decodeResult, encodeChallenge, encodeResult, importResult } from "./sr1.ts";

const web = process.argv[2];
if (!web) throw new Error("usage: bun tools/sr1/check_vectors.ts <web repo> [vectors.json]");
const file = process.argv[3] ?? new URL("../../docs/vectors/sr1.json", import.meta.url).pathname;
const { hashString } = await import(`${web}/src/game/engine/prng.ts`);
const { ENGINE_VERSION, INPUT_ACTIONS } = await import(`${web}/src/game/engine/types.ts`);
const { verifyLog } = await import(`${web}/src/lib/match/rules.ts`);

const vec = JSON.parse(readFileSync(file, "utf8"));
let pass = 0;
const fails: string[] = [];
const eq = (a: unknown, b: unknown) => JSON.stringify(sort(a)) === JSON.stringify(sort(b));
function sort(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(sort);
  if (v && typeof v === "object") return Object.fromEntries(Object.keys(v).sort().map((k) => [k, sort((v as any)[k])]));
  return v;
}
function check(name: string, cond: boolean, detail?: () => string) {
  if (cond) pass++;
  else fails.push(name + (detail ? `\n      ${detail()}` : ""));
}

check("engine version", vec.engineVersion === ENGINE_VERSION, () => `vectors ${vec.engineVersion} / web ${ENGINE_VERSION}`);
check("input actions", eq(vec.actions, INPUT_ACTIONS));
for (const c of vec.checksums) {
  const got = (hashString(c.input) >>> 0).toString(16).padStart(8, "0");
  check(`checksum "${c.input}"`, got === c.fnv1a, () => `web ${got} / lua ${c.fnv1a}`);
}

for (const c of vec.challenges) {
  const d = decodeChallenge(c.code, hashString);
  const got = d.ok ? { ok: true, ruleset: d.ruleset, engine: d.engine, seed: d.seed } : { ok: false, error: d.error };
  check(`challenge: ${c.name}`, eq(got, c.expect), () => `ts ${JSON.stringify(got)} / lua ${JSON.stringify(c.expect)}`);
  if (d.ok) {
    const re = encodeChallenge(d.ruleset, d.seed, d.engine, hashString);
    check(`challenge re-encode: ${c.name}`, re === c.code.replace(/\s+/g, ""));
  }
}

for (const r of vec.results) {
  const got = importResult(r.code, r.challenge, r.elapsedMs, { hashString, verifyLog });
  check(`result: ${r.name}`, eq(got, r.expect), () => `ts  ${JSON.stringify(sort(got))}\n      lua ${JSON.stringify(sort(r.expect))}`);
  const d = decodeResult(r.code, hashString);
  if (d.ok) {
    const re = encodeResult(d, hashString);
    check(`result re-encode: ${r.name}`, re === r.code.replace(/\s+/g, ""));
  }
}

console.log(`SR1 vectors (web engine v${ENGINE_VERSION}, vectors from web commit ${String(vec.webCommit).slice(0, 7)}): ${pass} passed, ${fails.length} failed`);
for (const f of fails) console.log("  FAIL " + f);
process.exit(fails.length ? 1 : 0);
